using OmniOps.Application.Common.Interfaces;
using System.Text.RegularExpressions;

namespace OmniOps.Infrastructure.Storage;

/// <summary>
/// Files on local disk (a Docker volume in deployment). Keys are generated by the server and checked
/// against a strict pattern, so a key can never escape the root directory.
/// </summary>
public sealed partial class LocalFileStore : IFileStore
{
    private readonly string _root;

    public LocalFileStore(string rootPath)
    {
        _root = Path.GetFullPath(rootPath);
    }

    public async Task SaveAsync(string key, Stream content, CancellationToken cancellationToken = default)
    {
        var path = Resolve(key);
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);

        // Write to a temp file first so a failed upload never leaves a truncated file under the real key.
        var temp = path + ".partial";
        await using (var file = new FileStream(temp, FileMode.Create, FileAccess.Write, FileShare.None, 81920, useAsync: true))
        {
            await content.CopyToAsync(file, cancellationToken);
        }

        File.Move(temp, path, overwrite: true);
    }

    public Task<Stream?> OpenReadAsync(string key, CancellationToken cancellationToken = default)
    {
        var path = Resolve(key);
        Stream? stream = File.Exists(path)
            ? new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.Read, 81920, useAsync: true)
            : null;
        return Task.FromResult(stream);
    }

    private string Resolve(string key)
    {
        if (!KeyPattern().IsMatch(key))
        {
            throw new ArgumentException("Invalid storage key.", nameof(key));
        }

        var path = Path.GetFullPath(Path.Combine(_root, key));
        if (!path.StartsWith(_root + Path.DirectorySeparatorChar, StringComparison.Ordinal))
        {
            throw new ArgumentException("Invalid storage key.", nameof(key));
        }

        return path;
    }

    [GeneratedRegex(@"^[a-zA-Z0-9-]+(/[a-zA-Z0-9-]+)*\.[a-z0-9]{2,5}$")]
    private static partial Regex KeyPattern();
}
